LibFuzzer-based fuzz driver for MiniSGL library.
Uses atheris for coverage-guided fuzzing.
Focuses on message deserialization and request parsing (avoids GPU/model operations).
"""
import sys
import atheris


def setup_minisgl():
    """Import minisgl modules after atheris instrumentation."""
    with atheris.instrument_imports():
        from minisgl.message.utils import deserialize_type, serialize_type
        from minisgl.core import SamplingParams
        # Note: Avoid importing GPU-dependent modules
    return deserialize_type, serialize_type, SamplingParams


def TestOneInput(data: bytes):
    """Fuzz target for MiniSGL library."""
    deserialize_type, serialize_type, SamplingParams = setup_minisgl.modules

    fdp = atheris.FuzzedDataProvider(data)

    # Choose which function to fuzz
    choice = fdp.ConsumeIntInRange(0, 2)

    try:
        if choice == 0:
            # Fuzz deserialize_type() with various data structures
            # Build a fuzzed dictionary that mimics message structure
            type_name = fdp.ConsumeUnicodeNoSurrogates(32)

            # Create nested data structures
            fuzz_data = {
                "__type__": type_name,
            }

            # Add random fields
            num_fields = fdp.ConsumeIntInRange(0, 10)
            for i in range(num_fields):
                key = fdp.ConsumeUnicodeNoSurrogates(16)
                value_type = fdp.ConsumeIntInRange(0, 4)
                if value_type == 0:
                    fuzz_data[key] = fdp.ConsumeInt(8)
                elif value_type == 1:
                    fuzz_data[key] = fdp.ConsumeFloat()
                elif value_type == 2:
                    fuzz_data[key] = fdp.ConsumeUnicodeNoSurrogates(64)
                elif value_type == 3:
                    fuzz_data[key] = fdp.ConsumeBool()
                elif value_type == 4:
                    fuzz_data[key] = None

            # Create a minimal cls_map
            cls_map = {"SamplingParams": SamplingParams}
            deserialize_type(cls_map, fuzz_data)

        elif choice == 1:
            # Fuzz SamplingParams with boundary values
            max_tokens = fdp.ConsumeInt(4)  # Could be negative or huge
            temperature = fdp.ConsumeFloat()  # Could be NaN, inf, negative
            top_k = fdp.ConsumeInt(4)
            top_p = fdp.ConsumeFloat()
            ignore_eos = fdp.ConsumeBool()

            params = SamplingParams(
                max_tokens=max_tokens,
                temperature=temperature,
                top_k=top_k,
                top_p=top_p,
                ignore_eos=ignore_eos,
            )

            # Test is_greedy property
            _ = params.is_greedy

        elif choice == 2:
            # Fuzz with nested list/dict structures
            def build_nested(fdp, depth=0):
                if depth > 5 or fdp.remaining_bytes() < 4:
                    return fdp.ConsumeUnicodeNoSurrogates(16)

                struct_type = fdp.ConsumeIntInRange(0, 2)
                if struct_type == 0:
                    # Dict
                    result = {}
                    num_items = fdp.ConsumeIntInRange(0, 3)
                    for _ in range(num_items):
                        key = fdp.ConsumeUnicodeNoSurrogates(8)
                        result[key] = build_nested(fdp, depth + 1)
                    return result
                elif struct_type == 1:
                    # List
                    result = []
                    num_items = fdp.ConsumeIntInRange(0, 3)
                    for _ in range(num_items):
                        result.append(build_nested(fdp, depth + 1))
                    return result
                else:
                    return fdp.ConsumeUnicodeNoSurrogates(16)

            nested_data = build_nested(fdp)
            if isinstance(nested_data, dict):
                nested_data["__type__"] = "SamplingParams"
                cls_map = {"SamplingParams": SamplingParams}
                deserialize_type(cls_map, nested_data)

    except (ValueError, TypeError, KeyError, AttributeError,
            IndexError, RecursionError, OverflowError):
        # Expected exceptions for invalid input
        pass
    except Exception as e:
        # Silently catch other exceptions
        pass


